    size_t maxConns = 4u;
    pool.init(maxConns, 1024u);

    std::string domain = FUZZ_PARAM_STR();
    if (domain.empty()) { FUZZ_BAIL(); }

    // Pick some connections
    unsigned count = (unsigned)(*FUZZ_PARAM(unsigned int) % (maxConns + 1));
    std::vector<std::shared_ptr<Connection>> conns;
    for (unsigned i = 0; i < count; ++i) {
        auto c = pool.pickConnection(domain);
        if (!c) break;
        conns.emplace_back(std::move(c));
    }

    // Release half of them to become idle
    for (size_t i = 0; i < conns.size(); ++i) {
        if ((i % 2) == 0) ConnectionPool::releaseConnection(conns[i]);
    }

    size_t idle = pool.idleConnections(domain);
    if (idle > maxConns) { FUZZ_BAIL(); }

    // Release remaining and shutdown
    for (size_t i = 0; i < conns.size(); ++i) {
        if ((i % 2) != 0) ConnectionPool::releaseConnection(conns[i]);
    }
    pool.shutdown();
}
