// Fuzz stub for Pistache::MPMCQueue<int, 8>::enqueue
// Goal: exercise success/failure paths without assuming exact capacity semantics
// (some ring buffers reserve one slot). We count successful enqueues until it fails.
{
    Pistache::MPMCQueue<int, 8> q;

    // Seed with a random number of attempts to push; stop when enqueue() returns false
    const unsigned int attempts = (*FUZZ_PARAM(unsigned int) % 16) + 1; // 1..16
    size_t successes = 0;

    for (unsigned int i = 0; i < attempts; ++i) {
        int v = static_cast<int>(*FUZZ_PARAM(unsigned int));
        bool ok = q.enqueue(v);
        if (ok) ++successes; else break; // queue reported full
    }

    // Property: after at least one failure, additional immediate enqueues are likely to fail
    // but we don't assert it strictly; just try a couple more opportunistically.
    for (int i = 0; i < 2; ++i) {
        int v = static_cast<int>(*FUZZ_PARAM(unsigned int));
        (void)q.enqueue(v);
    }

    // Try to dequeue as many as we think we enqueued to avoid leaving items behind
    size_t popped = 0; int tmp = 0;
    for (; popped < successes; ++popped) {
        bool got = q.dequeue(tmp);
        // Due to concurrent semantics, dequeue could return false if empty;
        // however in our single-threaded usage, items should be available until we've popped "successes" items.
        if (!got) break;
    }

    // Validation: we cannot pop more than successfully enqueued
    FUZZ_ASSERT(popped <= successes, "Dequeued more items than successfully enqueued");
}
// Validation summary: Enqueue exercised both success and potential full path; basic accounting checked.

// Fuzz stub for Pistache::MPMCQueue<int, 8>::dequeue
// Exercise empty dequeue, enqueue->dequeue round-trips, wrap-around interleaving.
{
    Pistache::MPMCQueue<int, 8> q;

    // 1) Empty dequeue should return false
    int out = 0;
    bool got_empty = q.dequeue(out);
    if (got_empty) {
        // It's unexpected to get a value from an empty queue in single-threaded scenario
        FUZZ_BAIL();
    }

    // 2) Enqueue a fuzz-chosen number of items (bounded), then dequeue them
    const unsigned int to_push = (*FUZZ_PARAM(unsigned int) % 6) + 1; // 1..6
    unsigned int pushed = 0;
    for (; pushed < to_push; ++pushed) {
        int v = static_cast<int>(*FUZZ_PARAM(unsigned int));
        if (!q.enqueue(v)) break; // stop if full
    }

    unsigned int popped = 0;
    for (; popped < pushed; ++popped) {
        if (!q.dequeue(out)) break;
        // Optionally touch the value to vary code paths
        (void)(out ^ 0x5A5A5A5A);
    }
    FUZZ_ASSERT(popped <= pushed, "Dequeued more items than enqueued");

    // 3) Interleave to exercise wrap-around: push-pop-push-pop
    for (int i = 0; i < 4; ++i) {
        int v1 = static_cast<int>(*FUZZ_PARAM(unsigned int));
        (void)q.enqueue(v1);
        (void)q.dequeue(out);
    }

    // 4) Drain remaining items (if any) without asserting availability
    while (q.dequeue(out)) { (void)out; }
}
