import random
import string
from typing import List

# Data type: hostname string
# Used by Experimental::ConnectionPool pickConnection and others expecting a non-empty domain key.
# We generate valid, interesting hostnames/domains including:
# - plain hostnames (alpha-numeric with hyphens)
# - domains with multiple labels
# - punycode-like xn-- labels
# - IPv4 literals
# - IPv6 literals in brackets (common in URLs; harmless as a key)
# - host:port forms (since some stubs pass Host header or Address which tolerate host:port)
# - localhost variants and common TLDs
# Keep total size <= 4096.

SAFE_TLDS = [
    "com", "org", "net", "io", "dev", "local", "example"
]

LABEL_CHARS = string.ascii_lowercase + string.digits + "-"

def _rand_label(rng: random.Random, min_len=1, max_len=20) -> str:
    L = rng.randint(min_len, max_len)
    # ensure start/end not hyphen to keep it well-formed
    if L == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    mid = ''.join(rng.choice(LABEL_CHARS) for _ in range(L))
    # fix leading/trailing hyphen
    if mid[0] == '-':
        mid = 'a' + mid[1:]
    if mid[-1] == '-':
        mid = mid[:-1] + 'b'
    return mid

def _rand_domain(rng: random.Random) -> str:
    # 2-5 labels
    n = rng.randint(2, 5)
    labels: List[str] = []
    for i in range(n-1):
        labels.append(_rand_label(rng, 1, rng.randint(3, 15)))
    labels.append(rng.choice(SAFE_TLDS))
    return '.'.join(labels)

def _rand_hostname(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.15:
        return "localhost"
    elif choice < 0.30:
        # simple single-label host
        return _rand_label(rng, 1, 20)
    elif choice < 0.55:
        return _rand_domain(rng)
    elif choice < 0.70:
        # punycode-like
        base = _rand_label(rng, 3, 10)
        dom = _rand_domain(rng)
        return f"xn--{base}.{dom}"
    elif choice < 0.85:
        # IPv4 literal
        return ".".join(str(rng.randint(0, 255)) for _ in range(4))
    else:
        # IPv6 literal in brackets
        hextet = lambda: format(rng.randint(0, 0xFFFF), 'x')
        parts = [hextet() for _ in range(rng.randint(2, 8))]
        return "[" + ":".join(parts) + "]"

def _maybe_port(rng: random.Random, host: str) -> str:
    # 40% chance to append :port (avoid if already bracketed IPv6 with port semantics undefined)
    if host.startswith('[') and host.endswith(']'):
        # For bracketed IPv6, occasionally add port
        if rng.random() < 0.4:
            return f"{host}:{rng.randint(1, 65535)}"
        return host
    if rng.random() < 0.4 and ':' not in host:
        return f"{host}:{rng.randint(1, 65535)}"
    return host

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Build a small corpus of candidates and pick one to vary distribution with seed
    candidates: List[str] = []
    for _ in range(rng.randint(3, 9)):
        h = _rand_hostname(rng)
        h = _maybe_port(rng, h)
        # Bound overall length to something reasonable (ConnectionPool keys, Host header cap)
        if len(h) > 256:
            h = h[:256]
        candidates.append(h)
    out = rng.choice(candidates)
    # Ensure non-empty per fuzzer constraints
    if not out:
        out = "example.com"
    return out.encode('utf-8')
